css:
.print-format { padding: 0 !important; margin: 0 !important; }
.mi4 { width: 96mm; font-family: "DejaVu Sans Mono", "Courier New", monospace; font-size: 11px; line-height: 1.3; color: #000; }
.mi4 table { width: 100%; border-collapse: collapse; }
.mi4 td { padding: 0 1px; vertical-align: top; }
.mi4 .kv td:first-child { width: 38%; }
.mi4 .c { text-align: center; }
.mi4 .r { text-align: right; white-space: nowrap; }
.mi4 .b { font-weight: bold; }
.mi4 .big { font-size: 13px; }
.mi4 .rule { border-top: 1px dashed #000; margin: 4px 0; }

.mi4 .small td { font-size: 0.85em; }
.mi4 .sig { margin-top: 18px; }
.mi4 .sig td { padding-top: 14px; border-top: 1px solid #000; text-align: center; width: 45%; }
.mi4 .sig td.gap { border: 0; width: 10%; }
.mi4 .sec { margin-top: 4px; }

html:
{%- set cur = {"fieldtype": "Currency", "options": doc.currency or frappe.db.get_value("Company", doc.company, "default_currency")} -%}
{%- set f = mobile_visit_bill_print(doc) -%}
<div class="mi4">
	<div class="c b big">{{ doc.company }}</div>
	{%- set tax_id = doc.get("company_tax_id") or frappe.db.get_value("Company", doc.company, "tax_id") %}
	{%- if tax_id %}<div class="c">{{ _("Tax ID") }}: {{ tax_id }}</div>{% endif %}
	<div class="c b">{{ _("BILL") }}</div>
	<div class="rule"></div>
	<table class="kv">
		<tr><td>{{ _("Visit") }}</td><td>{{ doc.name }}</td></tr>
		<tr><td>{{ _("Date") }}</td><td>{{ frappe.format(doc.visit_datetime, "Datetime")[:16] }}</td></tr>
		<tr><td>{{ _("Customer") }}</td><td>{{ doc.customer_name }}</td></tr>
		{%- if f.agent_name %}<tr><td>{{ _("Agent") }}</td><td>{{ f.agent_name }}</td></tr>{% endif %}
	</table>
	<div class="rule"></div>
	{%- if f.sale %}{% set sale = f.sale %}
	<div class="b">{{ _("SALES") }} · {{ sale.name }}</div>
	<table class="items">
		<tr class="b"><td>{{ _("Item") }}</td><td class="r">{{ _("Qty") }}</td><td class="r">{{ _("Rate") }}</td><td class="r">{{ _("Amount") }}</td></tr>
		{%- for item in sale.items %}
		<tr><td colspan="4">{{ item.item_name }}</td></tr>
		{%- set off = item.price_list_rate - item.rate if item.price_list_rate else 0 %}
		{%- if off > 0.004 %}
		<tr class="small"><td colspan="4">{{ _("List") }} {{ frappe.format(item.price_list_rate, cur) }} − {{ _("Disc.") }} {{ "%.2f" | format(off / item.price_list_rate * 100) }}% ({{ frappe.format(off, cur) }} / {{ item.uom }})</td></tr>
		{%- endif %}
		<tr><td></td><td class="r">{{ frappe.format(item.qty, {"fieldtype": "Float"}) }} {{ item.uom }}</td><td class="r">{{ frappe.format(item.rate, cur) }}</td><td class="r">{{ frappe.format(item.amount, cur) }}</td></tr>
		{%- endfor %}
	</table>
	<table class="kv totals sec">
		{%- if sale.discount_amount or f.line_discount %}
		<tr><td>{{ _("Subtotal") }}</td><td class="r">{{ frappe.format(sale.total, cur) }}</td></tr>
		{%- endif %}
		{%- if sale.discount_amount %}
		<tr><td>{{ _("Invoice discount") }}{% if sale.additional_discount_percentage %} ({{ "%g" | format(sale.additional_discount_percentage) }}%){% endif %}</td><td class="r">-{{ frappe.format(sale.discount_amount | abs, cur) }}</td></tr>
		{%- endif %}
		<tr><td>{{ _("Net Total") }}</td><td class="r">{{ frappe.format(sale.net_total, cur) }}</td></tr>
		{%- for tax in sale.taxes %}{% if tax.tax_amount %}
		<tr><td>{{ tax.description }}</td><td class="r">{{ frappe.format(tax.tax_amount, cur) }}</td></tr>
		{%- endif %}{% endfor %}
		{%- if sale.rounding_adjustment and f.payable != sale.grand_total %}
		<tr><td>{{ _("Grand Total") }}</td><td class="r">{{ frappe.format(sale.grand_total, cur) }}</td></tr>
		<tr><td>{{ _("Rounding adjustment") }}</td><td class="r">{{ frappe.format(sale.rounding_adjustment, cur) }}</td></tr>
		{%- endif %}
		<tr class="b"><td>{{ _("Sales total") }}</td><td class="r">{{ frappe.format(f.payable, cur) }}</td></tr>
	</table>
	<div class="rule"></div>
	{%- endif %}
	{%- for r in f.returns %}{% set against = r.return_against %}
	<div class="b">{{ _("RETURNS") }} · {{ r.name }}</div>
	<table class="items">
		<tr class="b"><td>{{ _("Item") }}</td><td class="r">{{ _("Qty") }}</td><td class="r">{{ _("Rate") }}</td><td class="r">{{ _("Amount") }}</td></tr>
		{%- for l in r.lines %}
		<tr><td colspan="4">{{ l.item_name }}</td></tr>
		<tr><td></td><td class="r">{{ frappe.format(l.qty, {"fieldtype": "Float"}) }} {{ l.uom }}</td><td class="r">{{ frappe.format(l.rate, cur) }}</td><td class="r">-{{ frappe.format(l.amount, cur) }}</td></tr>
		{%- if l.reason or l.condition %}
		<tr class="small"><td colspan="4">{% if against %}{{ _("against") }} {{ against }} · {% endif %}{{ l.reason or "" }}{% if l.condition %} · {{ _(l.condition) }}{% endif %}{% if l.remarks %} · {{ l.remarks }}{% endif %}</td></tr>
		{%- elif against %}
		<tr class="small"><td colspan="4">{{ _("against") }} {{ against }}</td></tr>
		{%- endif %}
		{%- endfor %}
		{%- if r.rounding %}
		<tr><td colspan="3">{{ _("Rounding") }}</td><td class="r">{{ frappe.format(-r.rounding, cur) }}</td></tr>
		{%- endif %}
	</table>
	{%- endfor %}
	{%- if f.returns %}
	<table class="kv totals sec">
		<tr class="b"><td>{{ _("Return total") }}</td><td class="r">-{{ frappe.format(f.return_total, cur) }}</td></tr>
		{%- for p in f.applied %}
		<tr><td>{{ _("Return credit applied") }} {{ p.invoice }}</td><td class="r">-{{ frappe.format(p.amount, cur) }}</td></tr>
		{%- endfor %}
		<tr><td>{{ _("Credit left on account") }}</td><td class="r">{{ frappe.format(f.credit_left, cur) }}</td></tr>
	</table>
	<div class="rule"></div>
	{%- endif %}
	<table class="kv totals">
		{%- if f.sale %}
		<tr class="b"><td>{{ _("Net payable") }}</td><td class="r">{{ frappe.format(f.net_payable, cur) }}</td></tr>
		<tr><td>{{ _("Paid (cash)") }}</td><td class="r">{{ frappe.format(f.paid, cur) }}</td></tr>
		<tr><td>{{ _("Balance") }}</td><td class="r">{{ frappe.format(f.balance, cur) }}</td></tr>
		{%- endif %}
		{%- for r in f.paid_previous %}
		<tr><td>{{ _("Paid (cash)") }} {{ r.sales_invoice }}</td><td class="r">{{ frappe.format(r.allocated, cur) }}</td></tr>
		{%- endfor %}
		<tr><td>{{ _("Previous Outstanding") }}</td><td class="r">{{ frappe.format(f.previous, cur) }}</td></tr>
		<tr class="b"><td>{{ _("Total Due") }}</td><td class="r">{{ frappe.format(f.previous + f.balance, cur) }}</td></tr>
	</table>
	<div class="rule"></div>
	<table class="sig"><tr><td>{{ _("Customer") }}</td><td class="gap"></td><td>{{ _("Agent") }}</td></tr></table>
</div>
